13	export const TaskListItem: React.FC<TaskListItemProps> = ({ checked, node: _node, ...props }) => {
14	  const { memo } = useMemoViewContext();
15	  const { readonly } = useMemoViewDerived();
16	  const checkboxRef = useRef<HTMLButtonElement>(null);
17	  const { mutate: updateMemo } = useUpdateMemo();
18	
19	  const handleChange = async (newChecked: boolean) => {
20	    // Don't update if readonly or no memo
21	    if (readonly || !memo) {
22	      return;
23	    }
24	
25	    // Find the task index by walking up the DOM
26	    const listItem = checkboxRef.current?.closest("li.task-list-item");
27	    if (!listItem) {
28	      return;
29	    }
30	
31	    // Get task index from data attribute, or calculate by counting
32	    const taskIndexStr = listItem.getAttribute("data-task-index");
33	    let taskIndex = 0;
34	
35	    if (taskIndexStr !== null) {
36	      taskIndex = parseInt(taskIndexStr);
37	    } else {
38	      // Fallback: Calculate index by counting all task list items in the entire memo
39	      // We need to search from the root memo content container, not just the nearest list
40	      // to ensure nested tasks are counted in document order
41	      let searchRoot = listItem.closest("[data-memo-content]");
42	
43	      // If memo content container not found, search from document body
44	      if (!searchRoot) {
45	        searchRoot = document.body;
46	      }
47	
48	      const allTaskItems = searchRoot.querySelectorAll(`li.${TASK_LIST_ITEM_CLASS}`);
49	      for (let i = 0; i < allTaskItems.length; i++) {
50	        if (allTaskItems[i] === listItem) {
51	          taskIndex = i;
52	          break;
53	        }
54	      }
55	    }
56	
57	    // Update memo content using the string manipulation utility
58	    const newContent = toggleTaskAtIndex(memo.content, taskIndex, newChecked);
59	    updateMemo({
60	      update: {
61	        name: memo.name,
62	        content: newContent,
63	      },
64	      updateMask: ["content", "update_time"],
65	    });
66	  };
67	
68	  // Override the disabled prop from remark-gfm (which defaults to true)
69	  return <Checkbox ref={checkboxRef} checked={checked} disabled={readonly} onCheckedChange={handleChange} className={props.className} />;
